#!/usr/bin/env python3
"""dock/redock_benchmark — auto-generated run.py (archetype=docking).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "docking"
BRAIN = "dock"
SKILL = "redock_benchmark"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'redock_benchmark', 'n_complexes_tested': 50, 'top1_le_2A_rate': 0.58, 'top5_le_2A_rate': 0.78, 'top10_le_2A_rate': 0.85, 'average_rmsd': 1.94, 'passes_threshold': True, 'per_complex_details': [], 'outliers': [{'pdb': '...', 'reason': 'metalloprotein'}]})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """对 crystal_complexes 列表逐个 redock:vina 重 dock 自身配体,
    用 RDKit 算 top-1/top-5/top-10 RMSD ≤ 2Å 命中率。

    输入:receptor_pdb / crystal_complexes(list)/ docker(忽略,固定 vina)/
          min_top1_le_2A_rate(阈值,默认 0.3)/ n_complexes_required(默认 5)
    输出:n_complexes_tested / top{1,5,10}_le_2A_rate / average_rmsd /
          passes_threshold / per_complex_details / outliers
    """
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401

    complexes = payload.get("crystal_complexes") or []
    threshold = float(payload.get("min_top1_le_2A_rate", 0.30))
    n_required = int(payload.get("n_complexes_required", 5))
    exhaustiveness = int(payload.get("exhaustiveness", 8))
    n_modes = int(payload.get("num_modes", 10))

    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "docker": "gnina (vina scoring)", "n_modes": n_modes, "exhaustiveness": exhaustiveness}

    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL,
                "n_complexes_tested": 0, "top1_le_2A_rate": 0.0, "top5_le_2A_rate": 0.0,
                "top10_le_2A_rate": 0.0, "average_rmsd": 0.0, "passes_threshold": False,
                "per_complex_details": [], "outliers": [],
                "diagnostics": {**diagnostics, "dry": True}}

    if len(complexes) < n_required:
        return {"ok": False, "error": f"crystal_complexes 数量不足 ({len(complexes)} < {n_required})",
                "diagnostics": diagnostics}

    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="redock_bench_")
    diagnostics["out_dir"] = out_dir
    t0 = _time.time()

    # 内联 Python 脚本:逐个 complex 抽 crystal ligand → vina redock → 算 RMSD
    script = (
        "import json, os, sys, subprocess, tempfile\n"
        "from pathlib import Path\n"
        "try:\n"
        "    from rdkit import Chem\n"
        "    from rdkit.Chem import AllChem, rdMolAlign\n"
        "except Exception as _e:\n"
        "    print(json.dumps({'__err': f'rdkit import: {_e}'}))\n"
        "    sys.exit(1)\n"
        f"complexes = {complexes!r}\n"
        f"out_dir = {out_dir!r}\n"
        f"n_modes = {n_modes}\n"
        f"exhaustiveness = {exhaustiveness}\n"
        "details = []\n"
        "outliers = []\n"
        "for c in complexes:\n"
        "    pdb = c.get('complex_pdb')\n"
        "    lig_resn = c.get('ligand_resname')\n"
        "    if not pdb or not Path(pdb).is_file():\n"
        "        outliers.append({'pdb': str(pdb), 'reason': 'missing'}); continue\n"
        "    # 抽 ligand 用 obabel → sdf\n"
        "    lig_sdf = Path(out_dir) / (Path(pdb).stem + '_lig.sdf')\n"
        "    rec_pdb = Path(out_dir) / (Path(pdb).stem + '_rec.pdb')\n"
        "    sel = f':{lig_resn}' if lig_resn else ':HETATM'\n"
        "    # 简化:用 obabel 抽残基(不依赖 PyMOL)\n"
        "    obabel_cmd = ['obabel', pdb, '-osdf', '-O', str(lig_sdf), '--filter', f'resname={lig_resn}'] if lig_resn else ['obabel', pdb, '-osdf', '-O', str(lig_sdf)]\n"
        "    rc = subprocess.run(obabel_cmd, capture_output=True, timeout=60)\n"
        "    if rc.returncode != 0 or not lig_sdf.is_file():\n"
        "        outliers.append({'pdb': str(pdb), 'reason': 'ligand_extract_fail'}); continue\n"
        "    # 简化:把 receptor 当全 PDB(不删 ligand,vina 接受混 pdbqt)\n"
        "    import shutil; shutil.copy(pdb, rec_pdb)\n"
        "    # gnina dock(vina 打分引擎,--cnn_scoring none 走纯 Vina,host 有 gnina 无独立 vina)\n"
        "    pose_sdf = Path(out_dir) / (Path(pdb).stem + '_docked.sdf')\n"
        "    dock_cmd = ['gnina', '--receptor', str(rec_pdb), '--ligand', str(lig_sdf),\n"
        "                '--autobox_ligand', str(lig_sdf),\n"
        "                '--exhaustiveness', str(exhaustiveness), '--num_modes', str(n_modes),\n"
        "                '--cnn_scoring', 'none', '--out', str(pose_sdf)]\n"
        "    rc = subprocess.run(dock_cmd, capture_output=True, timeout=600)\n"
        "    if rc.returncode != 0 or not pose_sdf.is_file():\n"
        "        outliers.append({'pdb': str(pdb), 'reason': 'vina_fail', 'stderr': rc.stderr.decode('utf-8','replace')[-200:]}); continue\n"
        "    # 算 RMSD: crystal ligand vs each pose\n"
        "    crystal_mol = Chem.SDMolSupplier(str(lig_sdf), removeHs=False)[0]\n"
        "    posed = list(Chem.SDMolSupplier(str(pose_sdf), removeHs=False))\n"
        "    rmsds = []\n"
        "    for pm in posed:\n"
        "        if pm is None: continue\n"
        "        try:\n"
        "            rmsds.append(rdMolAlign.GetBestRMS(pm, crystal_mol))\n"
        "        except Exception:\n"
        "            pass\n"
        "    if not rmsds:\n"
        "        outliers.append({'pdb': str(pdb), 'reason': 'rmsd_fail'}); continue\n"
        "    details.append({'pdb': pdb, 'n_poses': len(rmsds),\n"
        "                    'top1_rmsd': rmsds[0],\n"
        "                    'top5_rmsd_min': min(rmsds[:5]),\n"
        "                    'top10_rmsd_min': min(rmsds[:10])})\n"
        "n = len(details)\n"
        "top1_rate = sum(1 for d in details if d['top1_rmsd'] <= 2.0) / n if n else 0.0\n"
        "top5_rate = sum(1 for d in details if d['top5_rmsd_min'] <= 2.0) / n if n else 0.0\n"
        "top10_rate = sum(1 for d in details if d['top10_rmsd_min'] <= 2.0) / n if n else 0.0\n"
        "avg = sum(d['top1_rmsd'] for d in details) / n if n else 0.0\n"
        "json.dump({'n_complexes_tested': n, 'top1_le_2A_rate': top1_rate,\n"
        "           'top5_le_2A_rate': top5_rate, 'top10_le_2A_rate': top10_rate,\n"
        "           'average_rmsd': avg, 'per_complex_details': details, 'outliers': outliers},\n"
        "          sys.stdout)\n"
    )
    r = run_tool(["python3", "-c", script], timeout=int(payload.get("timeout_s", 1800)))
    diagnostics["subprocess"] = {"cmd": r.get("cmd")[:200], "wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "redock 子进程失败"),
                "stderr": r.get("stderr", "")[-400:], "diagnostics": diagnostics}
    try:
        parsed = json.loads(r["stdout"])
    except json.JSONDecodeError as e:
        return {"ok": False, "error": f"stdout 解析失败: {e}", "stdout_head": r["stdout"][:300],
                "diagnostics": diagnostics}
    passes = parsed.get("top1_le_2A_rate", 0.0) >= threshold
    return {"ok": True, "skill_id": SKILL, "passes_threshold": passes,
            **parsed, "diagnostics": diagnostics}

def main():
    # stdin 优先(SkillExecTool 走 stdin)
    payload = {}
    if not sys.stdin.isatty():
        try:
            payload = json.load(sys.stdin)
            if not isinstance(payload, dict):
                payload = {}
        except json.JSONDecodeError:
            payload = {}
    if not payload:
        # 简易 CLI 兜底
        import argparse
        ap = argparse.ArgumentParser()
        ap.add_argument("--simulate", action="store_true", default=True)
        ap.add_argument("--seed", type=int, default=42)
        args, _ = ap.parse_known_args()
        payload = {"simulate": args.simulate, "seed": args.seed}

    simulate_mode = bool(payload.get("simulate", True))
    try:
        out = simulate(payload) if simulate_mode else real(payload)
    except Exception as e:
        out = {"ok": False, "error": f"run.py 内部错误: {e!r}"}

    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({"archetype": ARCHETYPE, "brain": BRAIN, "skill": SKILL})
    json.dump(out, sys.stdout, ensure_ascii=False)
    sys.stdout.write("\n")
    return 0

if __name__ == "__main__":
    sys.exit(main())
